    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, person_id, id);

